import{_ as o,o as i,c as n,a2 as t}from"./chunks/framework.BN2sqjC1.js";const g=JSON.parse('{"title":"ADR-0066 — Cartelle dei sistemi di versione fuori dalla sincronizzazione ed elenco dei file non inviati (M26)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0066-vcs-esclusi-e-file-non-inviati.md","filePath":"adr/0066-vcs-esclusi-e-file-non-inviati.md"}'),a={name:"adr/0066-vcs-esclusi-e-file-non-inviati.md"};function s(l,e,c,d,r,u){return i(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0066-—-cartelle-dei-sistemi-di-versione-fuori-dalla-sincronizzazione-ed-elenco-dei-file-non-inviati-m26" tabindex="-1">ADR-0066 — Cartelle dei sistemi di versione fuori dalla sincronizzazione ed elenco dei file non inviati (M26) <a class="header-anchor" href="#adr-0066-—-cartelle-dei-sistemi-di-versione-fuori-dalla-sincronizzazione-ed-elenco-dei-file-non-inviati-m26" aria-label="Permalink to &quot;ADR-0066 — Cartelle dei sistemi di versione fuori dalla sincronizzazione ed elenco dei file non inviati (M26)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (2026-11-21; non ancora recepita nello spec)</td></tr><tr><td><strong>Data</strong></td><td>2026-11-21</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§3.4.2 (riga «Esclusi dal sync», <code>Specifications.md:1104</code>); §3.4.3 (<code>sync.db</code>, quarantena, <code>:1109</code>); §3.4.4 A (rilevamento locale, <code>:1138</code>); D-03 (quota, <code>:1958</code>); D-04; V-02; ADR-0009; ADR-0039; ADR-0047; ADR-0064</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td><strong>sì:</strong> §3.4.2 non elenca le cartelle dei sistemi di versione; §3.4.4 A non dice che cosa succede a un file già sincronizzato il cui path diventa escluso; nessuna sezione descrive l&#39;elenco dei file non inviati in Impostazioni › Sincronizzazione. Le righe da aggiornare nello spec (a cura dell&#39;owner) sono in «Conseguenze»</td></tr><tr><td><strong>Superfici</strong></td><td>desktop e workbench web (stesso core Go, desktop e WASM; prove: test di <code>shared/go/pathrules</code> e di <code>apps/desktop/internal/sync</code>, anche sotto <code>task test-wasm</code>, vitest di <code>SyncUnsent</code>, voce <code>sync.unsent</code> nel registro di parità); cloud: nessun codice nuovo, eredita la regola (rifiuto dei commit e ZIP), con un test d&#39;integrazione; console: nessun cambiamento</td></tr></tbody></table><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Richiesta dell&#39;owner del 2026-11-21: Clarae deve escludere <strong>sempre</strong> dalla sincronizzazione le cartelle dei sistemi di versione (<code>.git</code>, <code>.hg</code>, <code>.svn</code>) e mostrare in Impostazioni › Sincronizzazione <strong>l&#39;elenco dei file non inviati, con il motivo</strong>.</p><p>Lo stato di partenza:</p><ul><li><strong>Le esclusioni</strong> sono una sola funzione, <code>pathrules.IsExcluded</code> (<code>shared/go/pathrules/pathrules.go</code>): file di sistema (<code>.DS_Store</code>, <code>Thumbs.db</code>, <code>desktop.ini</code>), <code>*.tmp</code>, file di appoggio della scrittura atomica, <code>.trash/</code> (facoltativo) e i file locali della cartella di configurazione. La stessa funzione decide anche che cosa il core vede del vault: <code>vault.FS.Walk</code> (albero, indice, ricerca, ZIP locale), lo scan del sync (<code>walkLocal</code>), il pull (<code>skipExcluded</code>, <code>pull.go:427</code>), il rifiuto dei commit nei vault condivisi (<code>resolvePath</code>, <code>services/cloud/internal/sync/service.go:620</code>) e l&#39;export ZIP del cloud (<code>services/cloud/internal/export/service.go:140</code>).</li><li><strong>Le cartelle <code>.git</code> e simili</strong> non sono escluse: l&#39;esploratore le nasconde (<code>isHidden</code>, <code>packages/workbench/src/sidebar/FileExplorer.tsx:109</code>), ma il core le visita, le indicizza e le sincronizza. Un vault che è anche un repository manda nel cloud migliaia di oggetti, consuma quota e rallenta scan e push. Il merge dei file di un repository (<code>index</code>, <code>HEAD</code>, i pack) da due dispositivi produce copie di conflitto o un repository incoerente.</li><li><strong>Un file che diventa escluso è pericoloso.</strong> Il commento su <code>windowsReserved</code> in <code>pathrules.go</code> lo dice già: un file sincronizzato che diventa invisibile allo scan è preso per una cancellazione locale (<code>StateLocalDeleted</code>) e la cancellazione parte verso il cloud. Gli altri dispositivi aggiornati la ignorerebbero (il pull salta i path esclusi), ma un dispositivo ancora su 1.8.x la applicherebbe e manderebbe nel cestino la propria <code>.git</code>.</li><li><strong>I file che non partono</strong> non si vedono. Il motore li «parcheggia» (<code>Engine.park</code>, <code>push.go:382</code>: <code>Attempts = MaxAttempts</code> e un <code>LastError</code> a testo libero) per <code>FILE_TOO_LARGE</code>, per un errore di cifratura del path o del contenuto e per ogni rifiuto del server senza gestione dedicata (<code>PATH_INVALID</code>, <code>FORBIDDEN</code>, …); un file con troppe modifiche concorrenti finisce in <code>conflict</code> con «too many concurrent edits». I nomi che <code>pathrules.Normalize</code> rifiuta (per esempio <code>Riunione 10:30.md</code> creato da un altro programma) e i symlink sono saltati in silenzio da <code>vault.FS.walk</code>. Impostazioni › Sincronizzazione (<code>packages/workbench/src/settings/SyncSection.tsx</code>) mostra solo l&#39;errore dell&#39;engine, i conflitti e il <strong>conteggio</strong> della quarantena, che riguarda i file in arrivo (ADR-0039).</li></ul><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><h3 id="parte-1-—-cartelle-dei-sistemi-di-versione" tabindex="-1">Parte 1 — Cartelle dei sistemi di versione <a class="header-anchor" href="#parte-1-—-cartelle-dei-sistemi-di-versione" aria-label="Permalink to &quot;Parte 1 — Cartelle dei sistemi di versione&quot;">​</a></h3><p><strong>1. Regola.</strong> Un path è escluso dalla sincronizzazione se <strong>un suo segmento qualsiasi</strong> è uno di <code>.git</code>, <code>.hg</code>, <code>.svn</code>, <code>.bzr</code>, <code>.jj</code> (decisione dell&#39;owner del 2026-11-21: le tre richieste più Bazaar e Jujutsu).</p><ul><li>Vale per una cartella e per un file con quel nome: il <code>.git</code> dei worktree e dei submodule è un file.</li><li>Vale a qualunque profondità: <code>Progetti/sito/.git/…</code> è escluso come <code>.git/…</code> nella radice.</li><li>Il confronto ignora maiuscole e minuscole: la regola dipende solo dalla stringa del path, quindi dà lo stesso esito su tutti i dispositivi.</li><li>Restano sincronizzati <code>.gitignore</code>, <code>.gitattributes</code>, <code>.github/</code>, <code>.hgignore</code>: non sono il repository, sono contenuto dell&#39;utente.</li><li><code>CVS</code> e <code>_darcs</code> <strong>non</strong> sono nella regola: sono nomi plausibili per cartelle normali.</li><li>La regola è fissa, non configurabile (V-02, come le altre esclusioni di §3.4.2).</li></ul><p><strong>2. Un solo punto, i motivi classificati.</strong> <code>pathrules</code> espone <code>ExclusionReason(normalized string, excludeTrash bool) Reason</code>, con i valori <code>&quot;&quot;</code> (non escluso), <code>vcs</code>, <code>os-junk</code>, <code>temporary</code>, <code>trash</code>, <code>device-local</code>; <code>IsExcluded</code> diventa <code>ExclusionReason(…) != &quot;&quot;</code>, con lo stesso comportamento per le regole esistenti. La lista delle cartelle è <code>pathrules.VCSDirs</code>. Senza altro codice ne seguono quattro effetti:</p><ul><li><code>vault.FS.Walk</code> non scende nelle cartelle VCS: niente albero, indice, ricerca né ZIP locale. Su disco restano intatte: git, il terminale integrato (ADR-0064) e gli altri programmi le vedono come prima.</li><li>Il pull le salta (<code>skipExcluded</code>): un file VCS presente nel cloud non viene mai scritto né cancellato in locale.</li><li>Il cloud rifiuta con <code>PATH_INVALID</code> i nuovi commit su quei path nei vault condivisi (<code>resolvePath</code>). Un client 1.8.x che prova a mandarli riceve il rifiuto e parcheggia il file: nessun errore bloccante.</li><li>L&#39;export ZIP del cloud non li include.</li></ul><p><strong>3. Righe che diventano escluse: dimenticate, mai cancellate.</strong> All&#39;avvio dell&#39;engine, prima del primo scan, e a ogni scan, ogni riga di <code>sync_files</code> con un path escluso si <strong>dimentica</strong>: in una transazione (<code>DB.WithTx</code>) si cancellano la riga, la voce di <code>outbox</code> e l&#39;eventuale candidato in <code>pending_remote</code>. <strong>Non si invia nessuna operazione <code>delete</code>.</strong> Il file su disco non si tocca.</p><ul><li>È la regola per <strong>qualunque</strong> esclusione, presente o futura: un path che diventa escluso non è mai una cancellazione.</li><li>Le copie già nel cloud <strong>restano</strong> (decisione dell&#39;owner del 2026-11-21): nessun dispositivo le scarica o le cancella più, ma contano nella quota del proprietario (D-03) finché qualcuno non le toglie. È un debito dichiarato, senza pulizia automatica né azione dedicata in questa versione.</li></ul><h3 id="parte-2-—-elenco-dei-file-non-inviati" tabindex="-1">Parte 2 — Elenco dei file non inviati <a class="header-anchor" href="#parte-2-—-elenco-dei-file-non-inviati" aria-label="Permalink to &quot;Parte 2 — Elenco dei file non inviati&quot;">​</a></h3><p><strong>4. Core.</strong> <code>Engine.Unsent(ctx) ([]UnsentItem, error)</code> in <code>apps/desktop/internal/sync</code> (stesso codice sul desktop e nel core WASM):</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> UnsentItem</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Path      </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `json:&quot;path&quot;`</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      // vault-relative; for a skipped name, the raw name made valid UTF-8</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	IsDir     </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   `json:&quot;isDir&quot;`</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     // a whole folder (version control, trash, a folder with an invalid name)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Reason    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `json:&quot;reason&quot;`</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // see the table below</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Code      </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `json:&quot;code&quot;`</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      // server or local code (PATH_INVALID, FILE_TOO_LARGE, ENCRYPT_FAILED, …), &quot;&quot; when none</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Detail    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `json:&quot;detail&quot;`</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // the rest of the message (limit and size, server detail, path rule)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Retryable </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   `json:&quot;retryable&quot;`</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // RetryUnsent applies</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	Info      </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">bool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">   `json:&quot;info&quot;`</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      // informative (an excluded folder), not counted in Status.Unsent</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Fonte</th><th><code>Reason</code></th><th>Note</th></tr></thead><tbody><tr><td>Riga parcheggiata (<code>Attempts &gt;= MaxAttempts</code>)</td><td><code>too-large</code>, <code>encrypt-failed</code>, <code>share-root-move</code>, <code>rejected</code> (con codice)</td><td><code>Retryable</code></td></tr><tr><td>Riga in errore ancora in riprova (<code>0 &lt; Attempts &lt; MaxAttempts</code>)</td><td><code>retrying</code></td><td>con l&#39;ultimo errore</td></tr><tr><td>Riga in <code>conflict</code> con «too many concurrent edits»</td><td><code>too-many-conflicts</code></td><td>rimanda alla vista dei conflitti, non <code>Retryable</code></td></tr><tr><td>Riga trattenuta da un candidato al merge (ADR-0039)</td><td><code>awaiting-merge</code></td><td>transitoria</td></tr><tr><td>Nome che <code>pathrules.Normalize</code> rifiuta</td><td><code>invalid-name</code></td><td><code>Detail</code> = <code>pathrules.Error.Reason</code>; si risolve rinominando il file</td></tr><tr><td>Symlink</td><td><code>symlink</code></td><td>mai seguiti (§3.4.2)</td></tr><tr><td>Cartella esclusa per regola</td><td><code>vcs</code>, <code>trash</code></td><td><strong>una voce per cartella</strong>, <code>Info</code></td></tr></tbody></table><p>Non si elencano <code>os-junk</code>, <code>temporary</code> e <code>device-local</code>: sono rumore senza azione possibile, e il testo d&#39;aiuto della sezione li nomina. Il blocco dell&#39;intero engine (quota esaurita) resta il banner <code>status.error</code> esistente, senza dettaglio per file.</p><p><strong>5. Codici stabili.</strong> <code>park</code> diventa <code>park(ctx, row, code, detail)</code> e scrive <code>last_error</code> come <code>&quot;&lt;CODE&gt;: &lt;detail&gt;&quot;</code>, con i codici di <code>syncproto</code> o con codici locali (<code>ENCRYPT_FAILED</code>, <code>TOO_MANY_CONFLICTS</code>); un solo helper (<code>classifyLastError</code>) ricava <code>Reason</code> e <code>Code</code> dal testo, comprese le righe scritte dalle versioni precedenti. Il prefisso già letto da <code>folders.go:457</code> (<code>SHARE_ROOT_MOVE</code>) resta valido. <code>sync.db</code> non cambia schema.</p><p><strong>6. Raccolta senza un walk in più.</strong> <code>vault.FS.WalkReport(fn, skipped func(Skipped))</code> è il walk di sempre con una callback per ciò che salta (nome non valido, symlink, cartella esclusa con il suo motivo); <code>walkLocal</code> la usa e l&#39;engine tiene in memoria le voci saltate dall&#39;<strong>ultimo scan</strong>. Prima del primo scan l&#39;elenco di queste voci è vuoto.</p><p><strong>7. Riprova.</strong> <code>Manager.RetryUnsent(ctx, localID, paths)</code> azzera <code>Attempts</code> e <code>LastError</code> delle righe parcheggiate indicate (tutte, con <code>paths</code> vuoto), sotto il lock di esecuzione dell&#39;engine, e avvia un ciclo (<code>Kick</code>). Non vale per <code>too-many-conflicts</code>, che passa dalla risoluzione dei conflitti, né per le voci che si risolvono sul disco (<code>invalid-name</code>, <code>symlink</code>).</p><p><strong>8. Binding, stato ed eventi.</strong> <code>SyncAPI.Unsent(vaultID)</code> e <code>SyncAPI.RetryUnsent(vaultID, paths)</code> (generati con <code>task gen</code> nei binding Wails e in <code>web/src/workbench/core.gen.ts</code>). <code>Status</code> ha un campo <code>unsent</code>, il numero delle voci non informative: l&#39;evento <code>sync:status</code> esistente lo porta alla UI, che ricarica l&#39;elenco quando il numero o <code>lastSync</code> cambiano. Nessun evento nuovo.</p><p><strong>9. Interfaccia.</strong> In Impostazioni › Sincronizzazione, dopo quarantena e conflitti, un blocco «File non inviati» (<code>packages/workbench/src/settings/SyncUnsent.tsx</code>):</p><ul><li>voci raggruppate per motivo; per ognuna il path completo (con l&#39;estensione: è un elenco tecnico, ADR-0063 non si applica), il motivo tradotto (<code>sync.unsent.reason_&lt;reason&gt;</code>) e il dettaglio;</li><li>«Riprova» sulle voci <code>Retryable</code> e «Riprova tutti» (azione <code>sync:retry-unsent</code> con <code>feature</code>, come <code>sync:pause</code>);</li><li>le cartelle escluse in un <code>&lt;details&gt;</code> chiuso, «Cartelle escluse» (repository e cestino);</li><li>stato vuoto: «Tutti i file sono stati inviati»;</li><li>un testo d&#39;aiuto che elenca le esclusioni fisse di §3.4.2, VCS compresi.</li></ul><p><strong>10. Parità.</strong> Nuova voce <code>sync.unsent</code> in <code>shared/parity/features.yaml</code> (binding, azione, prove desktop e workbench sul core WASM). Nel workbench web le voci <code>invalid-name</code> e <code>symlink</code> non si presentano di fatto (il vault del browser non ha nomi del genere), ma il codice è lo stesso.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Escludere le cartelle VCS solo nel motore di sync, non in <code>IsExcluded</code>.</strong> Due regole divergenti; il cloud continuerebbe ad accettare i commit <code>.git</code> dei client vecchi, e l&#39;indice continuerebbe a visitare migliaia di file inutili. Scartata.</li><li><strong>Cancellare dal cloud i file VCS già caricati, automaticamente o con un pulsante.</strong> Libera quota, ma un dispositivo ancora su 1.8.x riceverebbe la cancellazione e manderebbe nel cestino la propria <code>.git</code>. Scartata per decisione dell&#39;owner; resta possibile in seguito, quando i client 1.8.x non saranno più in uso.</li><li><strong>Lasciare che lo scan tratti i file diventati esclusi come cancellazioni.</strong> È la perdita descritta nel Contesto. Scartata.</li><li><strong>Una colonna <code>last_code</code> in <code>sync.db</code>.</strong> Una migrazione per un dato che un prefisso codificato già porta. Scartata.</li><li><strong>Elencare anche <code>.DS_Store</code>, i temporanei e i file locali di <code>.clarae/</code>.</strong> Rumore senza azione possibile. Scartata.</li><li><strong>Esclusioni configurabili dall&#39;utente (sul modello di <code>.gitignore</code>).</strong> Fuori da V-02 e da §3.4.2, che vogliono un comportamento fisso e uguale su tutti i dispositivi. Scartata.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li><strong>Vault che sono repository.</strong> Il repository resta solo locale: per averlo su un altro dispositivo si usa git (remote), non Clarae. Le note del repository continuano a sincronizzarsi come prima.</li><li><strong>Copie già nel cloud.</strong> Restano e contano nella quota del proprietario (D-03); i dispositivi aggiornati non le toccano più. Un client 1.8.x su un vault <strong>privato</strong> continua a scambiarle con altri client 1.8.x (il cloud non vede i path); su un vault <strong>condiviso</strong> i suoi nuovi invii sono rifiutati e parcheggiati.</li><li><strong>Indice e ricerca.</strong> Le cartelle VCS escono dall&#39;indice alla prossima ricostruzione o aggiornamento: nessuna migrazione dell&#39;indice (<code>index.db</code> è derivato).</li><li><strong>Diagnosi.</strong> I file parcheggiati, i nomi non validi e i symlink diventano visibili all&#39;utente; i nuovi messaggi di <code>park</code> hanno un prefisso di codice stabile.</li><li><strong>Da rivedere:</strong> la pulizia dei file VCS già nel cloud, quando non ci saranno più client 1.8.x; un elenco analogo per i file <strong>in arrivo</strong> non applicati (quarantena e path esclusi dal pull), oggi solo contati.</li></ul><p><strong>Righe da aggiornare in <code>Specifications.md</code> (a cura dell&#39;owner):</strong></p><ul><li>§3.4.2, riga «Esclusi dal sync»: aggiungere «le cartelle dei sistemi di versione <code>.git</code>, <code>.hg</code>, <code>.svn</code>, <code>.bzr</code>, <code>.jj</code> (cartella o file, a qualunque profondità, senza distinzione di maiuscole) (ADR-0066)».</li><li>§3.4.4 A: «Un file già sincronizzato il cui path diventa escluso (§3.4.2) si dimentica in <code>sync.db</code> senza inviare cancellazioni; le copie nel cloud restano (ADR-0066)».</li><li>§3.4.3: i codici stabili in <code>last_error</code> (<code>&lt;CODE&gt;: &lt;detail&gt;</code>) e l&#39;elenco dei file non inviati (<code>SyncAPI.Unsent</code>, <code>SyncAPI.RetryUnsent</code>, <code>Status.unsent</code>).</li><li>Appendice C.4: riga dell&#39;ADR-0066.</li></ul>',32)])])}const h=o(a,[["render",s]]);export{g as __pageData,h as default};
